INSERT IGNORE INTO `uuid_map_refresh_tokens` (old_id, new_id) SELECT v, HEX(RANDOM_BYTES(16)) FROM (SELECT DISTINCT entity_id AS v FROM `audit_logs` WHERE entity_type = 'RefreshToken' AND entity_id IS NOT NULL) d;
INSERT IGNORE INTO `uuid_map_risk_feedback` (old_id, new_id) SELECT v, HEX(RANDOM_BYTES(16)) FROM (SELECT DISTINCT entity_id AS v FROM `audit_logs` WHERE entity_type = 'RiskFeedback' AND entity_id IS NOT NULL) d;
INSERT IGNORE INTO `uuid_map_sepa_payment_batches` (old_id, new_id) SELECT v, HEX(RANDOM_BYTES(16)) FROM (SELECT DISTINCT entity_id AS v FROM `audit_logs` WHERE entity_type = 'SepaPayment' AND entity_id IS NOT NULL) d;
INSERT IGNORE INTO `uuid_map_users` (old_id, new_id) SELECT v, HEX(RANDOM_BYTES(16)) FROM (SELECT DISTINCT entity_id AS v FROM `audit_logs` WHERE entity_type = 'User' AND entity_id IS NOT NULL) d;
CREATE TABLE `uuid_map_audit_other` AS SELECT entity_type, entity_id AS old_id FROM `audit_logs` WHERE 1 = 0;
ALTER TABLE `uuid_map_audit_other` MODIFY old_id BIGINT NOT NULL, ADD COLUMN new_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, ADD PRIMARY KEY (entity_type, old_id);
INSERT INTO `uuid_map_audit_other` (entity_type, old_id, new_id) SELECT entity_type, v, HEX(RANDOM_BYTES(16)) FROM (SELECT DISTINCT entity_type, entity_id AS v FROM `audit_logs` WHERE entity_id IS NOT NULL AND entity_type NOT IN ('Budget', 'BusinessArea', 'Contract', 'ContractDocument', 'ContractHistory', 'ContractTemplate', 'Counterparty', 'ElectronicInvoice', 'FinancialType', 'FinancialValue', 'Manager', 'Notification', 'Organization', 'PasswordResetToken', 'RefreshToken', 'RiskFeedback', 'SepaPayment', 'User')) d;
-- The random digits are stored first and formatted here, in a separate statement,
-- so every piece of a UUID comes from the same stored value by construction.
UPDATE `uuid_map_audit_logs` SET new_id = LOWER(CONCAT(SUBSTR(new_id,1,8),'-',SUBSTR(new_id,9,4),'-4',SUBSTR(new_id,14,3),'-',ELT(1 + CONV(SUBSTR(new_id,17,1),16,10) % 4,'8','9','a','b'),SUBSTR(new_id,18,3),'-',SUBSTR(new_id,21,12)));
