-- 4. The old organization id is kept: files uploaded before this release live under it.
ALTER TABLE `organizations` ADD COLUMN legacy_id BIGINT NULL;
UPDATE `organizations` SET legacy_id = id;

-- 5. A UUID twin next to every id column, filled through the maps.
ALTER TABLE `audit_logs` ADD COLUMN `entity_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `org_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `budgets` ADD COLUMN `business_area_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `organization_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `business_areas` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `organization_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `contract_documents` ADD COLUMN `contract_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `org_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `version_group_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `contract_history` ADD COLUMN `contract_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `modified_by__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `contract_manager` ADD COLUMN `contract_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `manager_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `contract_templates` ADD COLUMN `business_area_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `default_manager_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `org_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `contract_workflow_events` ADD COLUMN `actor_user_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `contract_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `contracts` ADD COLUMN `area_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `counterparty_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `financial_type_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `manager_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `organization_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `counterparties` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `organization_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `electronic_invoices` ADD COLUMN `contract_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `matched_by_user_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `matched_financial_value_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `org_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `sepa_batch_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `financial_types` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `organization_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `financial_values` ADD COLUMN `area_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `contract_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `financial_type_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `organization_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `invite_token` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `manager_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `invoice_line_items` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `invoice_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `managers` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `organization_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `ml_result_cache` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `org_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `notifications` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `org_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `user_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `organization_deletion_codes` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `organization_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `user_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `organizations` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `password_reset_token` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `user_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `pending_registrations` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `refresh_tokens` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `user_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `risk_feedback` ADD COLUMN `contract_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `org_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `submitted_by__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `roles` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `sepa_payment_batches` ADD COLUMN `contract_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `org_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `terms_acceptances` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `organization_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `user_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `totp_recovery_codes` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `user_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `users` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `manager_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `organization_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `role_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
ALTER TABLE `verification_token` ADD COLUMN `id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN `user_id__u` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL;
UPDATE `audit_logs` x JOIN `uuid_map_audit_logs` m ON m.old_id = x.`id` SET x.`id__u` = m.new_id;
UPDATE `audit_logs` x JOIN `uuid_map_organizations` m ON m.old_id = x.`org_id` SET x.`org_id__u` = m.new_id;
UPDATE `budgets` x JOIN `uuid_map_business_areas` m ON m.old_id = x.`business_area_id` SET x.`business_area_id__u` = m.new_id;
UPDATE `budgets` x JOIN `uuid_map_budgets` m ON m.old_id = x.`id` SET x.`id__u` = m.new_id;
UPDATE `budgets` x JOIN `uuid_map_organizations` m ON m.old_id = x.`organization_id` SET x.`organization_id__u` = m.new_id;
UPDATE `business_areas` x JOIN `uuid_map_business_areas` m ON m.old_id = x.`id` SET x.`id__u` = m.new_id;
UPDATE `business_areas` x JOIN `uuid_map_organizations` m ON m.old_id = x.`organization_id` SET x.`organization_id__u` = m.new_id;
UPDATE `contract_documents` x JOIN `uuid_map_contracts` m ON m.old_id = x.`contract_id` SET x.`contract_id__u` = m.new_id;
UPDATE `contract_documents` x JOIN `uuid_map_contract_documents` m ON m.old_id = x.`id` SET x.`id__u` = m.new_id;
UPDATE `contract_documents` x JOIN `uuid_map_organizations` m ON m.old_id = x.`org_id` SET x.`org_id__u` = m.new_id;
UPDATE `contract_documents` x JOIN `uuid_map_contract_documents` m ON m.old_id = x.`version_group_id` SET x.`version_group_id__u` = m.new_id;
UPDATE `contract_history` x JOIN `uuid_map_contracts` m ON m.old_id = x.`contract_id` SET x.`contract_id__u` = m.new_id;
UPDATE `contract_history` x JOIN `uuid_map_contract_history` m ON m.old_id = x.`id` SET x.`id__u` = m.new_id;
UPDATE `contract_history` x JOIN `uuid_map_users` m ON m.old_id = x.`modified_by` SET x.`modified_by__u` = m.new_id;
UPDATE `contract_manager` x JOIN `uuid_map_contracts` m ON m.old_id = x.`contract_id` SET x.`contract_id__u` = m.new_id;
